	// error (growth legitimately waits for the player's first router — pinned
	// by core/growth_test.odin), and the parser cannot see the final topology

growth_connectable :: proc(t: ^Topology, pos: [2]i32, span: i32) -> bool {
	span2 := i64(span) * i64(span)
	for i in 0..<len(t.node_alive) {
		if !t.node_alive[i] {
			continue
		}
		if t.node_kind[i] != .Junction {
			continue
		}
		d := t.node_pos[i] - pos
		if i64(d[0])*i64(d[0]) + i64(d[1])*i64(d[1]) <= span2 {
			return true
		}
	}
	return false
}
